  // Weekly muscle-balance view: which muscle groups actually got trained in
  // the last 7 days, and which didn't — reusing the exact same per-exercise
  // muscle lookup (fetchExerciseMuscles) that already powers the per-exercise
  // demo diagram, just aggregated across every distinct exercise logged this
  // week instead of looked up for one exercise at a time. A muscle counts as
  // "primary" for the week if any exercise this week trained it directly; if
  // it only ever showed up as some exercise's secondary muscle, it's "assisted"
  // — worked a bit, but never actually targeted.
  async function computeWeeklyMuscleStatus(weekEntries) {
    // Keep each distinct exercise name paired with the coarse muscle group
    // that was actually saved on that entry (the same one shown as the
    // colored badge in the log) — that's the fallback ground truth below.
    const byName = new Map();
    weekEntries.forEach((x) => {
      const nm = (x.exercise || "").trim();
      if (nm && !byName.has(nm)) byName.set(nm, x.muscleGroup || null);
    });
    const names = Array.from(byName.keys());
    const results = await Promise.all(names.map((n) => fetchExerciseMuscles(n)));
    const primarySet = new Set();
    const secondarySet = new Set();
    names.forEach((nm, i) => {
      const r = results[i];
      if (r && (r.primary || (r.secondary && r.secondary.length))) {
        if (r.primary) primarySet.add(r.primary);
        (r.secondary || []).forEach((s) => { if (s) secondarySet.add(s); });
        return;
      }
      // No fine-grained match in exercise_catalog for this exercise's name
      // (an unmapped or differently-spelled machine, say) — fall back to the
      // coarse group already saved with the entry rather than stranding a
      // clearly-logged, clearly-tagged exercise in "Not trained yet".
      const fineKeys = GROUP_TO_PRIMARY_MUSCLES[byName.get(nm)] || [];
      if (fineKeys.length === 1) {
        primarySet.add(fineKeys[0]);
      } else {
        // Group covers several fine muscles (e.g. "Legs") and we don't know
        // which one specifically — mark them all as assisted rather than
        // guess a single one outright.
        fineKeys.forEach((k) => secondarySet.add(k));
      }
    });
    // Primary always wins the tier if an exercise elsewhere also hit it as
    // secondary — being someone's direct target this week outranks being
    // incidental in another one.
    secondarySet.forEach((k) => { if (primarySet.has(k)) secondarySet.delete(k); });
    return { primarySet, secondarySet };
  }

  // Sept 12 2026, Jimmy: "can we make here the weeks muscle balance more pro
  // and less cluttery" + "interactive to be more" — the old version repeated
  // every one of the 16 muscles as a chip TWICE (once under "Trained this
  // week", once under "Not trained yet"), which was mostly the same
